#include <vector>
#include <string>
#include <unordered_set>

using namespace std;

class Solution {
public:
    vector<string> findWords(vector<string>& words) {
        vector<unordered_set<char>> rows = {
            {'q','w','e','r','t','y','u','i','o','p'},
            {'a','s','d','f','g','h','j','k','l'},
            {'z','x','c','v','b','n','m'}
        };

        vector<string> res;
        for (auto& word : words) {
            string w = word;
            transform(w.begin(), w.end(), w.begin(), ::tolower);
            for (auto& row : rows) {
                if (all_of(w.begin(), w.end(), [&](char c){ return row.count(c); })) {
                    res.push_back(word);
                    break;
                }
            }
        }
        return res;
    }
};
